// ACT III's quest book (game/phobosquests.js plays it): the folk of City State Phobos and Castle Velscour's hidden
// household ask for help. Places and people come from bm-phobos docs/PHOBOS.md and PHOBOS-LAYOUT.md: the eleven
// districts, the three hidden houses (the Pennyless, the Quiet Watch, the Ashwardens), the Rookery well's sewer-keepers,
// the Librarian and his household, the sacrificial idol, the prisoners of the pit stair, the five spires' parts.
//
// A quest: { id, at: district or wing id, name, giver: { name, title?, look?: folk whose art a new NPC wears, place?: where
//   a new NPC stands, hub?: a hidden house's own giver }, fl?: a castle giver's first floor of the wing, after?: quest id,
//   needChoice?: [quest id, option], text (the Quest Log), offer / progress (a speech bubble) / done (the turn-in), steps,
//   reward: { g: gold, x: experience (x errands' worth, by level), item?: rarity, skill?: points } }.
// A step: { t: type, label (the Quest Log line; {n} {need} {time}), ... }; d: a district (a castle quest's step in the
//   city), w: another wing, f: the wing floor it can be done on and above. The types:
//   slay {foe, name, title, at, guard}   kill {n, match}   collect {item, n, match, rate}   visit {at, n, hold, line(s)}
//   bell {mode ring|silence, n, at, guard (silence: the ringers), answer (ring: foes who come)}
//   deliver {item, from giver|carry|hub|name, to hub|name|giver, line}   rescue {name, look, at, guard, gm, to giver|hub:x|square|start}
//   clear {at, n, time}   survive {at, time, waves}   cache {n, at, item}   talk {who | name+look+at, line}
//   lord {foe: a ward lord of the district}   boss {f: the stair's guardian on that wing floor or above}
//   choice {prompt, opts: [{label, line, steps?, reward?, done?}] x2}
// Places: in the city square, street, far, house, hub, drawbridge, gate, sill, marches, notch, span; in the castle room,
// far, start, guard.
import { PHOBOS_FOLK, DISTRICTS, WINGS } from './phobos.js';

export const STEP_TYPES = ['slay', 'kill', 'collect', 'visit', 'bell', 'deliver', 'rescue', 'clear', 'survive', 'cache', 'talk', 'lord', 'boss', 'choice'];
export const CITY_PLACES = ['square', 'street', 'far', 'house', 'hub', 'drawbridge', 'gate', 'sill', 'marches', 'notch', 'span'];
export const CASTLE_PLACES = ['room', 'far', 'start', 'guard'];
export const HUB_DISTRICT = { pennyless: 'cinder', quietwatch: 'tanners', ashwardens: 'boneyards' };
/** How long each kind of text may run: a speech bubble holds about 130 characters, a Quest Log line about two lines. */
export const QUEST_LIMITS = { name: 40, text: 240, offer: 420, progress: 110, done: 300, label: 120, line: 100, prompt: 220, optLabel: 28, optLine: 160 };

