// ---------------------------------------------------------------------------------------------- resolving the art
const FOLK = Object.fromEntries(PHOBOS_FOLK.map((a) => [a.name, a]));
const DIST = Object.fromEntries(DISTRICTS.map((d) => [d.id, d]));
const WING = Object.fromEntries(WINGS.map((w) => [w.id, w]));
/** The foes a step's fights draw from: its district's (the city) or its wing's (the castle). */
export function poolOf(q, s = {}) {
  if (s.d) return DIST[s.d]?.foes || [];
  if (s.w) return WING[s.w]?.foes || [];
  return (DIST[q.at] || WING[q.at])?.foes || [];
}
export const lordsOf = (q, s = {}) => (DIST[s.d || q.at]?.bosses || []).filter(Boolean);
function resolve(q) {
  q.kind = DIST[q.at] ? 'city' : 'castle';
  q.where = (DIST[q.at] || WING[q.at])?.name || q.at;
  const g = q.giver; g.art = FOLK[g.look || g.name]?.id || null;
  const walk = (steps) => {
    for (const s of steps || []) {
      if (s.t === 'slay') s.art = poolOf(q, s).find((a) => a.name === s.foe)?.id || null;
      else if (s.t === 'lord') s.art = lordsOf(q, s).find((a) => a.name === s.foe)?.id || null;
      else if (s.t === 'rescue' || (s.t === 'talk' && !s.who)) s.art = FOLK[s.look || s.name]?.id || null;
      if (s.opts) for (const o of s.opts) walk(o.steps);
    }
  };
  walk(q.steps);
  return q;
}
export const PHOBOS_QUESTS = Q.map(resolve);
export const PQ_BY_ID = Object.fromEntries(PHOBOS_QUESTS.map((q) => [q.id, q]));
/** Every step of a quest, both branches of a choice included (for the tests). */
export function allSteps(q) { const out = []; const walk = (L) => { for (const s of L || []) { out.push(s); if (s.opts) for (const o of s.opts) walk(o.steps); } }; walk(q.steps); return out; }
